'use client';

import { useState, useEffect } from 'react';
import { api } from '@/lib/api';
import { Upload, Download, Users, GraduationCap, CheckCircle, AlertCircle } from 'lucide-react';

export default function BulkImportPage() {
    const [activeTab, setActiveTab] = useState<'students' | 'faculty'>('students');
    const [departments, setDepartments] = useState<any[]>([]);
    const [batches, setBatches] = useState<any[]>([]);
    const [csvText, setCsvText] = useState('');
    const [result, setResult] = useState<any>(null);
    const [loading, setLoading] = useState(false);

    useEffect(() => {
        Promise.all([
            api.get<any[]>('/api/admin/departments').catch(() => ({ success: false, data: [] } as any)),
            api.get<any[]>('/api/institution/batches').catch(() => ({ success: false, data: [] } as any)),
        ]).then(([d, b]) => {
            if (d.success) setDepartments(d.data);
            if (b.success) setBatches(b.data);
        });
    }, []);

    const parseCSV = (text: string): any[] => {
        const lines = text.trim().split('\n');
        if (lines.length < 2) return [];
        const headers = lines[0].split(',').map(h => h.trim().toLowerCase().replace(/\s+/g, '_'));
        return lines.slice(1).map(line => {
            const vals = line.split(',').map(v => v.trim());
            const obj: any = {};
            headers.forEach((h, i) => { obj[h] = vals[i] || ''; });
            return obj;
        });
    };

    const handleImport = async () => {
        setLoading(true);
        setResult(null);
        const parsed = parseCSV(csvText);
        if (parsed.length === 0) {
            setResult({ error: 'No valid rows found. Check your CSV format.' });
            setLoading(false);
            return;
        }

        try {
            if (activeTab === 'students') {
                const res = await api.post('/api/institution/bulk/students', { students: parsed });
                setResult(res.data);
            } else {
                const res = await api.post('/api/institution/bulk/faculty', { faculty: parsed });
                setResult(res.data);
            }
        } catch (err: any) {
            setResult({ error: err.message || 'Import failed' });
        }
        setLoading(false);
    };

    const studentTemplate = 'email,name,department_id,batch_code,roll_number\njohn@college.edu,John Doe,,CSE-A-2024,CS001\njane@college.edu,Jane Smith,,CSE-A-2024,CS002';
    const facultyTemplate = 'email,name,department_id,max_hours_per_week\ndr.smith@college.edu,Dr. Smith,,20\nprof.jones@college.edu,Prof. Jones,,18';

    return (
        <div>
            <h1 style={{ fontSize: 24, fontWeight: 700, color: '#142B34', fontFamily: 'Poppins', marginBottom: 8 }}>Bulk Import</h1>
            <p style={{ fontSize: 14, color: '#5a6a72', marginBottom: 24 }}>Import students and faculty from CSV. Users will be auto-created and can login immediately.</p>

            {/* Tabs */}
            <div style={{ display: 'flex', gap: 0, marginBottom: 24, borderBottom: '2px solid #e2e6ea' }}>
                {(['students', 'faculty'] as const).map(tab => (
                    <button
                        key={tab}
                        onClick={() => { setActiveTab(tab); setResult(null); setCsvText(''); }}
                        style={{
                            padding: '12px 24px', fontSize: 14, fontWeight: 600,
                            background: 'none', border: 'none', cursor: 'pointer',
                            color: activeTab === tab ? '#142B34' : '#8a9aa2',
                            borderBottom: activeTab === tab ? '2px solid #142B34' : '2px solid transparent',
                            marginBottom: -2, display: 'flex', alignItems: 'center', gap: 8,
                        }}
                    >
                        {tab === 'students' ? <GraduationCap size={16} /> : <Users size={16} />}
                        {tab === 'students' ? 'Students' : 'Faculty'}
                    </button>
                ))}
            </div>

            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 24 }}>
                {/* Left — Template & Input */}
                <div>
                    <div className="card" style={{ padding: 20, marginBottom: 16 }}>
                        <h3 style={{ fontSize: 14, fontWeight: 700, color: '#142B34', marginBottom: 8 }}>
                            <Download size={14} style={{ verticalAlign: 'sub', marginRight: 6 }} />
                            CSV Template
                        </h3>
                        <pre style={{
                            background: '#f5f7f9', padding: 12, borderRadius: 8, fontSize: 12,
                            fontFamily: 'monospace', overflow: 'auto', whiteSpace: 'pre',
                            border: '1px solid #e2e6ea', lineHeight: 1.6,
                        }}>
                            {activeTab === 'students' ? studentTemplate : facultyTemplate}
                        </pre>
                        <button
                            className="btn-secondary btn-sm"
                            onClick={() => setCsvText(activeTab === 'students' ? studentTemplate : facultyTemplate)}
                            style={{ marginTop: 8 }}
                        >
                            Use Template
                        </button>
                    </div>

                    {departments.length > 0 && (
                        <div className="card" style={{ padding: 16 }}>
                            <h4 style={{ fontSize: 12, fontWeight: 700, color: '#8a9aa2', textTransform: 'uppercase', marginBottom: 8 }}>Department IDs</h4>
                            {departments.map(d => (
                                <div key={d.id} style={{ fontSize: 12, marginBottom: 4 }}>
                                    <code style={{ background: '#f3f4f6', padding: '1px 6px', borderRadius: 3 }}>{d.id.slice(0, 8)}</code> — {d.name}
                                </div>
                            ))}
                        </div>
                    )}
                </div>

                {/* Right — Input */}
                <div>
                    <div className="card" style={{ padding: 20 }}>
                        <h3 style={{ fontSize: 14, fontWeight: 700, color: '#142B34', marginBottom: 12 }}>
                            Paste CSV Data
                        </h3>
                        <textarea
                            value={csvText}
                            onChange={(e) => setCsvText(e.target.value)}
                            style={{
                                width: '100%', minHeight: 200, padding: 12, borderRadius: 8,
                                border: '1px solid #e2e6ea', fontFamily: 'monospace', fontSize: 13,
                                resize: 'vertical', background: '#fafbfc',
                            }}
                            placeholder={`Paste your CSV here...\n\nFormat: ${activeTab === 'students' ? 'email,name,department_id,batch_code,roll_number' : 'email,name,department_id,max_hours_per_week'}`}
                        />
                        <div style={{ marginTop: 12, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                            <span style={{ fontSize: 12, color: '#8a9aa2' }}>
                                {csvText ? `${parseCSV(csvText).length} rows detected` : 'No data'}
                            </span>
                            <button className="btn-primary" onClick={handleImport} disabled={!csvText.trim() || loading}>
                                <Upload size={16} /> {loading ? 'Importing...' : `Import ${activeTab === 'students' ? 'Students' : 'Faculty'}`}
                            </button>
                        </div>
                    </div>

                    {/* Results */}
                    {result && (
                        <div className="card" style={{ marginTop: 16, padding: 20 }}>
                            {result.error ? (
                                <div style={{ display: 'flex', alignItems: 'center', gap: 8, color: '#DC2626' }}>
                                    <AlertCircle size={18} /> {result.error}
                                </div>
                            ) : (
                                <>
                                    <div style={{ display: 'flex', alignItems: 'center', gap: 8, color: '#16A34A', marginBottom: 12 }}>
                                        <CheckCircle size={18} /> <strong>{result.created} {activeTab} imported successfully</strong>
                                    </div>
                                    {result.errors?.length > 0 && (
                                        <div style={{ marginTop: 8 }}>
                                            <p style={{ fontSize: 13, fontWeight: 600, color: '#DC2626', marginBottom: 4 }}>{result.errors.length} errors:</p>
                                            {result.errors.map((err: any, i: number) => (
                                                <div key={i} style={{ fontSize: 12, color: '#991b1b', padding: '2px 0' }}>
                                                    {err.email}: {err.error}
                                                </div>
                                            ))}
                                        </div>
                                    )}
                                </>
                            )}
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
}
